try (Res r = new Res()) {          // close() prints "closed"
    System.out.println("work");
    throw new IllegalStateException("boom");
}

try (Res r = new Res()) {          // close() succeeds
    throw new IllegalStateException("body failed");
} catch (Exception e) {
    System.out.println(e.getMessage());
}

try (Res r = new Res()) {          // close() throws IOException("flush failed")
    System.out.println("work done");
} catch (Exception e) {
    System.out.println("caught: " + e.getMessage());
}

try (Res r = new Res()) {          // close() throws IOException("close failed")
    throw new IllegalStateException("body failed");
} catch (Exception e) {
    System.out.println(e.getMessage() + " / " + e.getSuppressed().length);
}

try (Connection c = dataSource.getConnection();
     PreparedStatement ps = c.prepareStatement(sql);
     ResultSet rs = ps.executeQuery()) {
    // use rs
}

try (Res r = new Res()) {          // close() prints "closed"
    System.out.println("work");
} finally {
    System.out.println("finally");
}

class Res implements AutoCloseable {
    @Override public void close() throws ??? { }
}

// A.close() throws IOException("A close failed")
// B.close() throws IOException("B close failed")
try (A a = new A(); B b = new B()) {
    throw new IllegalStateException("body failed");
} catch (Exception e) {
    System.out.println(e.getMessage() + " suppressed=" + e.getSuppressed().length);
}

